<script setup lang="ts">
import {imageDownloadUrl, imagePreviewUrl} from '../utils/imageDelivery'
import type {SelectableFile} from '~~/schemas/main.dto'
import type {AssetFile, AssetFolder, AssetListingPage, AssetSource} from '~~/schemas/image-storage'
import {hasConfirmedGenerationPrice} from '~~/schemas/generation-billing'
import {generationPriceLabel, type GenerationPrice} from '../utils/generationPrice'
import {assetFromImageUrl, assetSelectionLimit, MAX_ASSET_FAVOURITES, validateAssetUploads} from '~/utils/assetPreferences'
import {selectImageRange} from '../utils/imageSelection'
const props = withDefaults(defineProps<{selectionMode?: 'single' | 'multiple'; selectedUrls?: string[]; acceptedExtensions?: string[]; maxSelection?: number; selectionCap?: number; initialPath?: string; initialScope?: 'all' | 'shared'; sharedOnly?: boolean; title?: string}>(), {selectedUrls: () => [], acceptedExtensions: () => [], selectionCap: 20, initialPath: '/', initialScope: 'all', sharedOnly: false, title: 'Library'})
const emit = defineEmits<{'update:selectedUrls': [urls: string[]]; select: [file: SelectableFile]; confirm: [files: SelectableFile[]]; navigate: [path: string]; deleted: [urls: string[]]}>()
type View = 'all' | 'uploads' | 'generated' | 'favourites' | 'folder' | 'shared'
type ShareTarget = {id: string; username: string; displayName: string}
type Grant = {id: string; recipientUserId: string; permission: 'view' | 'edit'; username: string; displayName: string; createdAt: string}
const toast = useToast()
const session = useAccount()
const requestFetch = useRequestFetch()
const favourites = useAssetFavourites()
const browserElement = ref<HTMLElement>()
const view = ref<View>(props.initialScope === 'shared' ? 'shared' : props.initialPath === '/' ? 'all' : 'folder')
const folderPath = ref(props.initialPath)
const currentFolder = ref<AssetFolder>()
const folderTrail = ref<AssetFolder[]>([])
const files = ref<AssetFile[]>([])
const directories = ref<AssetFolder[]>([])
const rootFolders = ref<AssetFolder[]>([])
const sources = ref<AssetSource[]>([])
const sourceUserId = ref('')
const rootCursor = ref<string>()
const nextCursor = ref<string>()
const foldersLoading = ref(false)
const search = ref('')
const keyword = ref('')
const loading = ref(true)
const loadingMore = ref(false)
const errorMessage = ref('')
const uploading = ref(false)
const deleting = ref(false)
const creating = ref(false)
const newFolderOpen = ref(false)
const newFolderName = ref('')
const newFolderInput = ref<HTMLInputElement>()
const fileInput = ref<HTMLInputElement>()
const density = ref<'compact' | 'comfortable'>('comfortable')
const selection = ref<string[]>([])
const selectionAnchor = ref('')
const selectedMetadata = ref(new Map<string, AssetFile>())
const preview = ref<AssetFile>()
const backgroundRemovalSources = ref<string[]>([])
function openBackgroundRemoval(urls: string[]) { backgroundRemovalSources.value = [...urls]; preview.value = undefined }
async function useCutout(url: string) { backgroundRemovalSources.value = []; await navigateTo({path: '/edit', query: {source: url}}) }
function cutoutCompleted() { void refresh(); void refreshFolders() }
const unavailable = ref(new Set<string>())
const deleteTarget = ref<{files?: AssetFile[]; directory?: AssetFolder}>()
const shareTarget = ref<AssetFile | AssetFolder>()
const shareUsers = ref<ShareTarget[]>([])
const grants = ref<Grant[]>([])
const shareRecipient = ref('')
const shareLoading = ref(false)
const shareSaving = ref(false)
const shareError = ref('')
const dragDepth = ref(0)
let requestNumber = 0
let searchTimer: ReturnType<typeof setTimeout> | undefined
let listingAbort: AbortController | undefined
let focusBeforeDialog: HTMLElement | null = null
const isPicker = computed(() => Boolean(props.selectionMode))
const isShared = computed(() => view.value === 'shared')
const selectionLimit = computed(() => assetSelectionLimit(props.selectionMode, props.maxSelection, props.selectionCap))
const favouriteSet = computed(() => new Set(favourites.urls.value))
const canWrite = computed(() => currentFolder.value ? canEditAsset(currentFolder.value) : !isShared.value)
const uploadPath = computed(() => currentFolder.value?.url ?? (view.value === 'folder' ? folderPath.value : '/'))
const scopeTitle = computed(() => currentFolder.value?.name ?? ({all: 'Your library', uploads: 'Uploads', generated: 'Generated images', favourites: 'Favorites', folder: folderPath.value.split('/').filter(Boolean).at(-1) ?? 'Folders', shared: 'Shared with me'})[view.value])
const displayFiles = computed(() => files.value)
const selectedSet = computed(() => new Set(selection.value))
const selectedFiles = computed(() => selection.value.flatMap(url => { const file = selectedMetadata.value.get(url) ?? files.value.find(item => item.url === url); return file ? [file] : [] }))
const canDeleteSelection = computed(() => selectedFiles.value.length === selection.value.length && selectedFiles.value.length > 0 && selectedFiles.value.every(canEditAsset))
const breadcrumbs = computed(() => { const parts = folderPath.value.split('/').filter(Boolean); return [{name: 'Folders', path: '/'}, ...parts.map((name, index) => ({name, path: '/' + parts.slice(0, index + 1).join('/')}))] })
const emptyTitle = computed(() => keyword.value ? 'No matching images' : view.value === 'favourites' ? 'Keep your favorites close' : isShared.value ? 'A place for shared ideas' : 'Your collection starts here')
const groups = computed(() => {
  if (!isShared.value || currentFolder.value) return [{key: 'library', source: undefined as AssetSource | undefined, files: files.value, dirs: directories.value}]
  const map = new Map<string, {key: string; source?: AssetSource; files: AssetFile[]; dirs: AssetFolder[]}>()
  for (const file of files.value) { const source = file.sharedBy ?? file.source; const key = source?.userId ?? 'shared'; if (!map.has(key)) map.set(key, {key, source, files: [], dirs: []}); map.get(key)!.files.push(file) }
  for (const folder of directories.value) { const source = folder.sharedBy ?? folder.source; const key = source?.userId ?? 'shared'; if (!map.has(key)) map.set(key, {key, source, files: [], dirs: []}); map.get(key)!.dirs.push(folder) }
  return [...map.values()]
})
function canEditAsset(asset: AssetFile | AssetFolder) { const owner = session.account.value?.userId; return Boolean(!isShared.value && owner && asset.ownerUserId === owner && !asset.sharedBy && asset.permissions?.edit === true) }
function canShareAsset(asset: AssetFile | AssetFolder) { const owner = session.account.value?.userId; return Boolean(!isShared.value && owner && asset.ownerUserId === owner && !asset.sharedBy && asset.permissions?.share === true) }
type PricedAsset = AssetFile & GenerationPrice
function generated(file: AssetFile) { return (file as PricedAsset).category === 'generated' }
function imageReady(file: AssetFile) { return !generated(file) || hasConfirmedGenerationPrice(file as PricedAsset) }
function assetPrice(file: AssetFile) {
  if (file.category === 'processed') {
    const purpose = file.processingPurpose === 'pipeline' ? 'pipeline processing'
      : file.processingPurpose === 'background-removal' ? 'background removal' : 'local processing'
    return `$0 provider charge · ${purpose}`
  }
  return generated(file) ? generationPriceLabel(file as PricedAsset) : ''
}
function permitted(file: AssetFile) { return imageReady(file) && (!isPicker.value || selectionLimit.value !== 0) && (!props.acceptedExtensions.length || props.acceptedExtensions.some(extension => file.name.toLowerCase().endsWith('.' + extension.replace(/^\./, '').toLowerCase()))) }
function syncSelection(urls: readonly string[]) { selection.value = [...new Set(urls.filter(url => { const file = assetFromImageUrl(url); return file && permitted(file) }))].slice(0, selectionLimit.value) }
watch(() => props.selectedUrls, syncSelection, {immediate: true, deep: true})
watch(() => [props.maxSelection, props.selectionCap, props.selectionMode, props.acceptedExtensions], () => syncSelection(selection.value), {deep: true})
watch(() => [view.value, folderPath.value, currentFolder.value?.id, sourceUserId.value, search.value, keyword.value, props.selectionMode, props.maxSelection, props.selectionCap, props.acceptedExtensions.join(',')], () => { selectionAnchor.value = '' }, {flush: 'sync'})
watch(() => props.initialPath, path => { if (!isShared.value && path !== folderPath.value) enterFolder(path) })
watch(search, value => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { keyword.value = value.trim(); void refresh() }, 250) })
watch(sourceUserId, () => { currentFolder.value = undefined; folderTrail.value = []; void refresh() })
watch(session.epoch, () => {
  requestNumber += 1
  listingAbort?.abort()
  files.value = []; directories.value = []; rootFolders.value = []; sources.value = []
  selection.value = []; selectionAnchor.value = ''; selectedMetadata.value.clear(); grants.value = []; shareUsers.value = []
  preview.value = undefined; currentFolder.value = undefined; folderTrail.value = []
  backgroundRemovalSources.value = []
  shareTarget.value = undefined; deleteTarget.value = undefined; newFolderOpen.value = false
  uploading.value = false; deleting.value = false; creating.value = false; shareLoading.value = false; shareSaving.value = false
}, {flush: 'sync'})
watch(newFolderOpen, async open => { if (open) { await nextTick(); newFolderInput.value?.focus() } })
watch([newFolderOpen, deleteTarget, preview, shareTarget, backgroundRemovalSources], async () => {
  const open = newFolderOpen.value || Boolean(deleteTarget.value || preview.value || shareTarget.value) || backgroundRemovalSources.value.length > 0
  if (open && !focusBeforeDialog) focusBeforeDialog = document.activeElement instanceof HTMLElement ? document.activeElement : null
  await nextTick()
  if (open) browserElement.value?.querySelector<HTMLElement>('[role="dialog"] input, [role="dialog"] button')?.focus()
  else { if (focusBeforeDialog?.isConnected) focusBeforeDialog.focus(); focusBeforeDialog = null }
})
function safeMessage(error: unknown, fallback: string) { const e = error as {data?: {statusMessage?: string}; statusMessage?: string}; return e?.data?.statusMessage ?? e?.statusMessage ?? fallback }
function appendPage(page: AssetListingPage) {
  const known = new Set(files.value.map(file => file.url)); files.value.push(...page.files.filter(file => !known.has(file.url)))
  const knownDirs = new Set(directories.value.map(dir => dir.id)); directories.value.push(...(page.dirs ?? []).filter(dir => !knownDirs.has(dir.id)))
  for (const file of page.files) if (selection.value.includes(file.url)) selectedMetadata.value.set(file.url, file)
  if (page.sources) sources.value = [...new Map([...sources.value, ...page.sources].map(source => [source.userId, source])).values()]
  if (page.folder) currentFolder.value = page.folder
  nextCursor.value = page.nextCursor
}
async function refreshFolders(more = false) {
  if (foldersLoading.value || (more && !rootCursor.value) || props.sharedOnly) return
  foldersLoading.value = true
  const epoch = session.epoch.value
  try { const page = await requestFetch<AssetListingPage>('/api/files', {query: {path: '/', limit: 100, ...(more ? {cursor: rootCursor.value} : {})}}); if (epoch !== session.epoch.value) return; rootFolders.value = more ? [...rootFolders.value, ...(page.dirs ?? []).filter(dir => !rootFolders.value.some(known => known.id === dir.id))] : page.dirs ?? []; rootCursor.value = page.nextCursor }
  catch { /* Main listing provides the retry action. */ } finally { foldersLoading.value = false }
}
async function fetchPage(cursor?: string) {
  if (view.value === 'favourites') {
    const result = await requestFetch<{files: AssetFile[]}>('/api/assets/resolve', {method: 'POST', body: {urls: favourites.urls.value}, signal: listingAbort?.signal})
    return {files: result.files.filter(file => !keyword.value || `${file.name} ${file.folder}`.toLocaleLowerCase().includes(keyword.value.toLocaleLowerCase()))}
  }
  if (!keyword.value && (view.value === 'folder' || (isShared.value && currentFolder.value))) {
    return requestFetch<AssetListingPage>('/api/files', {query: {path: view.value === 'folder' ? folderPath.value : '/', ...(currentFolder.value?.id ? {folderId: currentFolder.value.id} : {}), limit: 60, cursor}, signal: listingAbort?.signal})
  }
  return requestFetch<AssetListingPage>('/api/assets', {query: {scope: isShared.value ? 'shared' : view.value === 'uploads' || view.value === 'generated' ? view.value : 'all', path: view.value === 'folder' ? folderPath.value : '/', ...(currentFolder.value?.id ? {folderId: currentFolder.value.id} : {}), ...(isShared.value && sourceUserId.value ? {sourceUserId: sourceUserId.value} : {}), query: keyword.value, limit: 60, cursor}, signal: listingAbort?.signal})
}
async function refresh() {
  selectionAnchor.value = ''
  const number = ++requestNumber; const epoch = session.epoch.value; listingAbort?.abort(); listingAbort = new AbortController()
  loading.value = true; loadingMore.value = false; files.value = []; directories.value = []; nextCursor.value = undefined; errorMessage.value = ''
  try { const page = await fetchPage(); if (number === requestNumber && epoch === session.epoch.value) appendPage(page) }
  catch (error) { if (number === requestNumber && epoch === session.epoch.value) errorMessage.value = safeMessage(error, 'Could not load your images. Please try again.') }
  finally { if (number === requestNumber) loading.value = false }
}
async function loadMore() {
  if (!nextCursor.value || loadingMore.value) return
  const number = requestNumber; const epoch = session.epoch.value; loadingMore.value = true; errorMessage.value = ''
  try { const page = await fetchPage(nextCursor.value); if (number === requestNumber && epoch === session.epoch.value) appendPage(page) }
  catch (error) { if (number === requestNumber) errorMessage.value = safeMessage(error, 'Could not load more images. Please try again.') }
  finally { if (number === requestNumber) loadingMore.value = false }
}
function changeView(next: View) { view.value = next; folderPath.value = '/'; currentFolder.value = undefined; folderTrail.value = []; search.value = ''; keyword.value = ''; clearTimeout(searchTimer); emit('navigate', '/'); void refresh() }
function enterFolder(path: string) { folderPath.value = path; view.value = 'folder'; currentFolder.value = undefined; folderTrail.value = []; emit('navigate', path); void refresh() }
function enterDirectory(folder: AssetFolder) {
  if (isShared.value) { folderTrail.value.push(folder); currentFolder.value = folder; void refresh() }
  else { folderPath.value = folder.path; currentFolder.value = folder; view.value = 'folder'; emit('navigate', folder.path); void refresh() }
}
function sharedBreadcrumb(index: number) { folderTrail.value = folderTrail.value.slice(0, index + 1); currentFolder.value = folderTrail.value.at(-1); void refresh() }
function choose(file: AssetFile, event?: Pick<MouseEvent, 'shiftKey'>) {
  if (!permitted(file)) return
  const visible = groups.value.flatMap(group => group.files).filter(permitted)
  const result = selectImageRange(selection.value, visible.map(item => item.url), file.url, {anchor: selectionAnchor.value, shift: event?.shiftKey, limit: selectionLimit.value, single: props.selectionMode === 'single'})
  selectionAnchor.value = result.anchor
  if (result.limited) toast.add({title: `Select up to ${selectionLimit.value} images`, description: 'The range was limited to the available selection slots.', color: 'warning'})
  for (const item of visible) if (result.selection.includes(item.url)) selectedMetadata.value.set(item.url, item)
  selection.value = result.selection
  emit('update:selectedUrls', [...selection.value]); emit('select', file)
}
function clearSelection() { selection.value = []; selectionAnchor.value = ''; selectedMetadata.value.clear(); emit('update:selectedUrls', []) }
function toggleFavourite(file: AssetFile) { if (!favouriteSet.value.has(file.url) && favourites.urls.value.length >= MAX_ASSET_FAVOURITES) { toast.add({title: `Save up to ${MAX_ASSET_FAVOURITES} favorites`, color: 'warning'}); return }; favourites.toggle(file.url); if (view.value === 'favourites') void refresh() }
function markUnavailable(url: string) { unavailable.value = new Set([...unavailable.value, url]) }
function openPreview(file: AssetFile) { if (imageReady(file)) preview.value = file }
function confirmSelection() { emit('confirm', selectedFiles.value.filter(permitted)) }
async function resolveSelected() {
  const urls = selection.value.filter(url => !selectedMetadata.value.has(url))
  if (!urls.length) return
  const epoch = session.epoch.value
  try {
    const result = await requestFetch<{files: AssetFile[]}>('/api/assets/resolve', {method: 'POST', body: {urls}})
    if (epoch === session.epoch.value) for (const file of result.files) selectedMetadata.value.set(file.url, file)
  } catch { /* Keep confirmation disabled until selected images can be verified. */ }
}
async function uploadFiles(chosen: File[]) {
  if (uploading.value || !canWrite.value) return
  const invalid = validateAssetUploads(chosen); if (invalid) { toast.add({title: 'Could not upload images', description: invalid, color: 'error'}); return }
  const body = new FormData(); body.append('path', uploadPath.value); chosen.forEach(file => body.append('files', file)); uploading.value = true
  const epoch = session.epoch.value
  try {
    const result = await $fetch<{saved: string[]; savedFiles: AssetFile[]; failed: Array<{filename: string; reason: string}>}>('/api/upload', {method: 'POST', body})
    if (epoch !== session.epoch.value) return
    if (result.saved.length) toast.add({title: `${result.saved.length} image${result.saved.length === 1 ? '' : 's'} uploaded`, color: 'success'})
    if (result.failed.length) toast.add({title: 'Some images could not be uploaded', description: result.failed.map(file => `${file.filename}: ${file.reason}`).join('\n'), color: 'error'})
    if (isPicker.value && result.savedFiles.length) { const uploaded = result.savedFiles.filter(permitted); for (const file of uploaded) selectedMetadata.value.set(file.url, file); selection.value = props.selectionMode === 'single' ? uploaded.slice(0, selectionLimit.value).map(file => file.url) : [...new Set([...selection.value, ...uploaded.map(file => file.url)])].slice(0, selectionLimit.value); emit('update:selectedUrls', [...selection.value]) }
    if (view.value === 'generated' || view.value === 'favourites') changeView('uploads'); else await refresh(); await refreshFolders()
  } catch (error) { if (epoch === session.epoch.value) toast.add({title: 'Upload failed', description: safeMessage(error, 'Please try again.'), color: 'error'}) }
  finally { uploading.value = false; if (fileInput.value) fileInput.value.value = '' }
}
function onFilesChanged(event: Event) { const input = event.target as HTMLInputElement; if (input.files?.length) void uploadFiles([...input.files]) }
function dragEnter(event: DragEvent) { if (canWrite.value && event.dataTransfer?.types.includes('Files')) { event.preventDefault(); dragDepth.value += 1 } }
function dragLeave() { dragDepth.value = Math.max(0, dragDepth.value - 1) }
function dropFiles(event: DragEvent) { event.preventDefault(); dragDepth.value = 0; if (canWrite.value && event.dataTransfer?.files.length) void uploadFiles([...event.dataTransfer.files]) }
async function createFolder() {
  const name = newFolderName.value.trim(); if (!name || creating.value || !canWrite.value) return; creating.value = true
  const epoch = session.epoch.value
  try { await $fetch('/api/createFolder', {method: 'POST', body: {path: uploadPath.value, name}}); if (epoch !== session.epoch.value) return; newFolderOpen.value = false; newFolderName.value = ''; await Promise.all([refresh(), refreshFolders()]); if (epoch === session.epoch.value) toast.add({title: `Folder “${name}” created`, color: 'success'}) }
  catch (error) { if (epoch === session.epoch.value) toast.add({title: 'Could not create folder', description: safeMessage(error, 'Please try again.'), color: 'error'}) } finally { if (epoch === session.epoch.value) creating.value = false }
}
async function deleteEntries() {
  const target = deleteTarget.value; if (!target || deleting.value || (target.directory ? !canEditAsset(target.directory) : !target.files?.length || !target.files.every(canEditAsset))) return; deleting.value = true
  const epoch = session.epoch.value
  const deletedUrls: string[] = []
  try {
    if (target.directory) { await $fetch('/api/deleteFileOrFolder', {method: 'DELETE', body: {path: target.directory.url, entryType: 'directory'}}); if (epoch !== session.epoch.value) return; const folder = target.directory; deletedUrls.push(...selectedFiles.value.filter(file => file.ownerUserId === folder.ownerUserId && (file.folder === folder.path || file.folder.startsWith(folder.path + '/'))).map(file => file.url)); for (const url of deletedUrls) favourites.remove(url) }
    else for (const file of target.files ?? []) { if (epoch !== session.epoch.value) return; await $fetch('/api/deleteFileOrFolder', {method: 'DELETE', body: {path: file.url, entryType: 'file'}}); if (epoch !== session.epoch.value) return; deletedUrls.push(file.url); favourites.remove(file.url) }
    toast.add({title: target.directory ? 'Folder deleted' : `${deletedUrls.length} image${deletedUrls.length === 1 ? '' : 's'} deleted`, color: 'success'}); deleteTarget.value = undefined
  } catch (error) { if (epoch === session.epoch.value) { deleteTarget.value = undefined; toast.add({title: 'Deletion stopped', description: safeMessage(error, 'Refresh and try again.'), color: 'error'}) } }
  finally { if (epoch === session.epoch.value) { selection.value = selection.value.filter(url => !deletedUrls.includes(url)); if (deletedUrls.length) { emit('update:selectedUrls', [...selection.value]); emit('deleted', deletedUrls) }; if (preview.value && deletedUrls.includes(preview.value.url)) preview.value = undefined; await Promise.all([refresh(), refreshFolders()]); if (epoch === session.epoch.value) deleting.value = false } }
}
async function openSharing(asset: AssetFile | AssetFolder) {
  if (!asset.id || !canShareAsset(asset)) return
  preview.value = undefined; shareTarget.value = asset; shareRecipient.value = ''; shareError.value = ''; shareLoading.value = true
  const epoch = session.epoch.value
  try { const [targets, existing] = await Promise.all([requestFetch<{users: ShareTarget[]}>('/api/assets/share-targets'), requestFetch<{shares: Grant[]}>(`/api/assets/${asset.id}/shares`)]); if (epoch !== session.epoch.value || shareTarget.value?.id !== asset.id) return; shareUsers.value = targets.users; grants.value = existing.shares }
  catch (error) { if (epoch === session.epoch.value) shareError.value = safeMessage(error, 'Could not load sharing settings.') } finally { if (epoch === session.epoch.value) shareLoading.value = false }
}
async function saveShare() {
  if (!shareTarget.value?.id || !shareRecipient.value || shareSaving.value) return; shareSaving.value = true; shareError.value = ''
  const epoch = session.epoch.value; const assetId = shareTarget.value.id
  try { await $fetch(`/api/assets/${assetId}/shares`, {method: 'POST', body: {recipientUserId: shareRecipient.value}}); if (epoch !== session.epoch.value) return; const result = await requestFetch<{shares: Grant[]}>(`/api/assets/${assetId}/shares`); if (epoch !== session.epoch.value || shareTarget.value?.id !== assetId) return; grants.value = result.shares; shareRecipient.value = ''; toast.add({title: 'Sharing updated', color: 'success'}) }
  catch (error) { if (epoch === session.epoch.value) shareError.value = safeMessage(error, 'Could not share this item.') } finally { if (epoch === session.epoch.value) shareSaving.value = false }
}
async function revokeShare(grant: Grant) {
  if (!shareTarget.value?.id || shareSaving.value) return; shareSaving.value = true; shareError.value = ''
  const epoch = session.epoch.value; const assetId = shareTarget.value.id
  try { await $fetch(`/api/assets/${assetId}/shares/${grant.recipientUserId}`, {method: 'DELETE'}); if (epoch === session.epoch.value && shareTarget.value?.id === assetId) grants.value = grants.value.filter(item => item.recipientUserId !== grant.recipientUserId) }
  catch (error) { if (epoch === session.epoch.value) shareError.value = safeMessage(error, 'Could not remove access.') } finally { if (epoch === session.epoch.value) shareSaving.value = false }
}
function onKeydown(event: KeyboardEvent) {
  const dialog = browserElement.value?.querySelector<HTMLElement>('[role="dialog"]'); if (!dialog) return
  if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); if (!deleting.value && !creating.value && !shareSaving.value) { preview.value = undefined; deleteTarget.value = undefined; newFolderOpen.value = false; shareTarget.value = undefined; backgroundRemovalSources.value = [] } }
  if (event.key === 'Tab') { const focusable = [...dialog.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), [tabindex="0"]')]; const first = focusable[0]; const last = focusable.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() } }
}
onMounted(() => { void refresh(); void refreshFolders(); void resolveSelected(); window.addEventListener('keydown', onKeydown, {capture: true}) })
onBeforeUnmount(() => { requestNumber += 1; listingAbort?.abort(); clearTimeout(searchTimer); window.removeEventListener('keydown', onKeydown, {capture: true}) })
</script>

<template>
  <section ref="browserElement" class="asset-browser" :class="{'asset-browser--picker': isPicker}" @dragenter="dragEnter" @dragleave="dragLeave" @dragover.prevent @drop="dropFiles">
    <div class="asset-library-header"><div><span class="workspace-eyebrow">{{ sharedOnly ? 'From your organization' : 'Your visual collection' }}</span><h1>{{ title }}</h1><p>{{ sharedOnly ? 'Files and folders shared with you, organized by the person they came from.' : 'Gather product photos, keep your references close, and share a collection with your team.' }}</p></div><div v-if="canWrite" class="asset-toolbar-actions"><button class="asset-button asset-button--secondary" type="button" aria-label="New folder" @click="newFolderOpen = true"><UIcon name="i-lucide-folder-plus" /><span class="asset-button-label">New folder</span></button><button class="asset-button" type="button" :disabled="uploading" @click="fileInput?.click()"><UIcon :name="uploading ? 'i-lucide-loader-circle' : 'i-lucide-upload'" :class="{'asset-spin': uploading}" />{{ uploading ? 'Uploading…' : 'Upload images' }}</button></div><input ref="fileInput" class="asset-hidden-input" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.gif,.bmp,.tif,.tiff,.heic,image/png,image/jpeg,image/webp,image/gif,image/bmp,image/tiff,image/heic" aria-label="Upload images" @change="onFilesChanged" /></div>
    <div class="asset-rail" aria-label="Asset library">
