      <label v-if="isShared && sources.length" class="asset-source-filter"><span>From</span><select v-model="sourceUserId" aria-label="Sharing source"><option value="">Everyone</option><option v-for="source in sources" :key="source.userId" :value="source.userId">{{ source.displayName }} ({{ source.username }})</option></select></label>
      <label class="asset-search"><UIcon name="i-lucide-search" /><input v-model="search" type="search" :placeholder="`Search ${scopeTitle.toLowerCase()}`" aria-label="Search assets" /></label>
